// STATE
var currentPage=1,promptGerado='',clausulaCount=0,maxStepReached=1;
var TOTAL_FORM_PAGES=3;
var elistData={suspeitas:[],artigos:[]};
var PERFIS=['Construtora / Empreiteira licitante','Advogado / Departamento jurídico','Gestor público / Servidor','Controlador interno / Auditor','Tribunal de Contas (TCE/TCU)','Consultor independente'];
var FOCOS=['Direcionamento e restrição à competitividade (art. 9º)','Exigências de habilitação excessivas ou desnecessárias','Qualificação técnica desproporcionada (atestados, acervos)','Qualificação econômico-financeira abusiva (art. 70)','Especificação de marca ou produto exclusivo','Critério de julgamento inadequado para o objeto','Prazo de execução incompatível ou exíguo','Cláusulas de responsabilidade e risco desequilibradas','Vedações indevidas (subcontratação, consórcio)','Ausência ou insuficiência do projeto básico (art. 18)','Reajuste, revisão e equilíbrio econômico-financeiro','Sanções e penalidades desproporcionais','Prazos de impugnação e recurso (art. 82)','Sigilo indevido ou falta de publicidade','Critérios de desempate e benefícios ME/EPP (LC 123/2006)','Vícios formais e redação ambígua'];

function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function showToast(msg,dur){if(!dur)dur=3000;var t=document.getElementById('toast');t.innerHTML=msg;t.classList.add('show');setTimeout(function(){t.classList.remove('show');},dur);}
function mascaraValor(el){var v=el.value.replace(/\D/g,'');if(!v){el.value='';return;}el.value='R$ '+(parseInt(v,10)/100).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});}
function appendTexto(id,texto){var el=document.getElementById(id);if(!el)return;if(el.value&&!el.value.endsWith(' '))el.value+='. ';el.value+=texto;el.focus();}

function ea(id){var inp=document.getElementById(id+'-input'),v=inp.value.trim();if(!v){showToast('Digite um valor antes de adicionar.');return;}if(elistData[id]&&elistData[id].includes(v)){showToast('Item já adicionado.');inp.value='';return;}if(!elistData[id])elistData[id]=[];elistData[id].push(v);inp.value='';er(id);inp.focus();}
function es(id,v){if(!elistData[id])elistData[id]=[];if(elistData[id].includes(v)){showToast('Item já adicionado.');return;}elistData[id].push(v);er(id);}
function edel(id,i){elistData[id].splice(i,1);er(id);}
function er(id){var c=document.getElementById(id+'-items');if(!c)return;c.innerHTML=elistData[id].map(function(t,i){return '<div class="elist-item"><span class="elist-text">'+esc(t)+'</span><button class="elist-del" onclick="edel(\''+id+'\','+i+')">×</button></div>';}).join('');}

function toggleChk(id){var c=document.getElementById('chk-'+id),l=document.getElementById('chk-lbl-'+id);c.checked=!c.checked;l.classList.toggle('checked',c.checked);}
function getChecked(gridId){return Array.from(document.querySelectorAll('#'+gridId+' input:checked')).map(function(c){return c.value;});}

function adicionarClausula(titulo,texto){
  if(!titulo)titulo='';if(!texto)texto='';
  clausulaCount++;var id='cl-'+clausulaCount;
  var div=document.createElement('div');div.className='clausula-bloco';div.id=id;
  div.innerHTML='<div class="clausula-header" onclick="toggleClausula(\''+id+'\')"><span class="clausula-num">Cláusula '+clausulaCount+'</span><input type="text" class="clausula-titulo-input" id="'+id+'-titulo" value="'+esc(titulo)+'" placeholder="Ex: Habilitação jurídica, Qualificação técnica\u2026" onclick="event.stopPropagation()" onfocus="event.stopPropagation()"><button class="clausula-del" onclick="event.stopPropagation();removerClausula(\''+id+'\')" title="Remover">\u00d7</button></div><div class="clausula-body open" id="'+id+'-body"><textarea id="'+id+'-texto" rows="4" placeholder="Cole ou digite o texto desta cl\u00e1usula\u2026">'+esc(texto)+'</textarea></div>';
  document.getElementById('clausulas-area').appendChild(div);
}
function toggleClausula(id){document.getElementById(id+'-body').classList.toggle('open');}
function removerClausula(id){var el=document.getElementById(id);if(el)el.remove();}
function getClausulas(){var items=[];document.querySelectorAll('.clausula-bloco').forEach(function(bl){var id=bl.id;var t=document.getElementById(id+'-titulo');var tx=document.getElementById(id+'-texto');var titulo=t?t.value.trim():'';var texto=tx?tx.value.trim():'';if(titulo||texto)items.push({titulo:titulo,texto:texto});});return items;}

function setStep(n){
  if(n>maxStepReached)maxStepReached=n;
  for(var i=1;i<=5;i++){var s=document.getElementById('step-'+i);s.classList.remove('active','done');if(i<n)s.classList.add('done');else if(i===n)s.classList.add('active');s.style.cursor=i<=maxStepReached?'pointer':'default';s.style.opacity=i<=maxStepReached?'1':'0.5';(function(st){s.onclick=st<=maxStepReached?function(){navigateToStep(st);}:null;})(i);}
}
function navigateToStep(n){
  if(n>maxStepReached)return;
  if(n<=TOTAL_FORM_PAGES){document.getElementById('section-prompt').style.display='none';document.getElementById('section-result').style.display='none';document.getElementById('section-form').style.display='block';for(var i=1;i<=TOTAL_FORM_PAGES;i++)document.getElementById('page-'+i).style.display=i===n?'block':'none';currentPage=n;setStep(n);window.scrollTo({top:0,behavior:'smooth'});}
  else if(n===4){document.getElementById('section-form').style.display='none';document.getElementById('section-result').style.display='none';document.getElementById('section-prompt').style.display='block';setStep(4);window.scrollTo({top:0,behavior:'smooth'});}
  else if(n===5){if(!document.getElementById('doc-content').innerHTML.trim())return;document.getElementById('section-form').style.display='none';document.getElementById('section-prompt').style.display='none';document.getElementById('section-result').style.display='block';setStep(5);window.scrollTo({top:0,behavior:'smooth'});}
}
function goPage(n){if(n>currentPage&&!validatePage(currentPage))return;document.getElementById('page-'+currentPage).style.display='none';currentPage=n;document.getElementById('page-'+n).style.display='block';setStep(n);window.scrollTo({top:0,behavior:'smooth'});}
function validatePage(n){
  if(n===1){if(!document.getElementById('orgao').value.trim()){showToast('Informe o \u00f3rg\u00e3o licitante.');return false;}if(!document.getElementById('modalidade').value){showToast('Selecione a modalidade licit\u00e1toria.');return false;}if(!document.getElementById('objeto').value.trim()){showToast('Descreva o objeto da licita\u00e7\u00e3o.');return false;}}
  if(n===2){var textoEdital=document.getElementById('texto-edital').value.trim();var clausulas=getClausulas();if(!textoEdital&&clausulas.length===0){showToast('Insira o texto do edital ou adicione ao menos uma cl\u00e1usula.');return false;}}
  if(n===3){if(getChecked('focos-grid').length===0){showToast('Selecione ao menos um foco de an\u00e1lise.');return false;}}
  return true;
}
function voltarForm(){document.getElementById('section-prompt').style.display='none';document.getElementById('section-form').style.display='block';document.getElementById('page-3').style.display='block';currentPage=3;setStep(3);window.scrollTo({top:0,behavior:'smooth'});}
function voltarPrompt(){document.getElementById('section-result').style.display='none';document.getElementById('section-prompt').style.display='block';setStep(4);window.scrollTo({top:0,behavior:'smooth'});}
function toggleOutro(id){
  var sel=document.getElementById(id);
  var outro=document.getElementById(id+'-outro');
  if(!sel||!outro)return;
  if(sel.value==='_outro'){outro.style.display='block';outro.focus();}
  else outro.style.display='none';
}
function toggleFinalidadeOutro(){toggleOutro('finalidade');}
