function collectData(){
  var dataAb=document.getElementById('data-abertura').value;
  var dataFormatada=dataAb?new Date(dataAb+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'}):'';
  var finalidadeMap={impugnar:'subsidiar impugna\u00e7\u00e3o ao edital',participar:'avaliar riscos antes de participar da licita\u00e7\u00e3o',elaborar:'verificar edital em fase de elabora\u00e7\u00e3o',auditoria:'auditoria ou controle interno/externo',juridico:'elabora\u00e7\u00e3o de parecer jur\u00eddico'};
  var fin=document.getElementById('finalidade').value;
  if(fin==='_outro'){var fo=document.getElementById('finalidade-outro');fin=fo&&fo.value.trim()?fo.value.trim():'_outro';}
  var _resolveOutro=function(id){var s=document.getElementById(id);if(!s)return'';if(s.value==='_outro'){var o=document.getElementById(id+'-outro');return o&&o.value.trim()?o.value.trim():'';}return s.value;};
  return{orgao:document.getElementById('orgao').value.trim(),numEdital:document.getElementById('num-edital').value.trim(),modalidade:_resolveOutro('modalidade'),regimeExec:_resolveOutro('regime-exec'),valorEstimado:document.getElementById('valor-estimado').value.trim(),dataAbertura:dataFormatada,objeto:document.getElementById('objeto').value.trim(),textoEdital:document.getElementById('texto-edital').value.trim(),clausulas:getClausulas(),perfis:(function(){var p=getChecked('perfil-grid');var o=document.getElementById('perfil-outro');if(o&&o.value.trim())p.push(o.value.trim());return p;})(),focos:getChecked('focos-grid'),suspeitas:(elistData.suspeitas||[]).slice(),artigos:(elistData.artigos||[]).slice(),finalidade:fin.startsWith('_')?fin.slice(1)||fin:(finalidadeMap[fin]||fin),obs:document.getElementById('obs-extras').value.trim()};
}

function gerarPrompt(){
  if(!validatePage(3))return;
  var d=collectData();
  var linhas=['Voc\u00ea \u00e9 um especialista em direito administrativo, licita\u00e7\u00f5es e contratos p\u00fablicos no Brasil, com dom\u00ednio profundo da Lei 14.133/2021 (Nova Lei de Licita\u00e7\u00f5es), jurisprud\u00eancia do TCU e dos Tribunais de Contas Estaduais.','','FINALIDADE DA AN\u00c1LISE: '+d.finalidade+'.',d.perfis.length?'PERFIL DO SOLICITANTE: '+d.perfis.join(', ')+'.':'','','IDENTIFICA\u00c7\u00c3O DO EDITAL:','- \u00d3rg\u00e3o licitante: '+d.orgao,'- N\u00famero do edital/processo: '+d.numEdital,'- Modalidade: '+(d.modalidade||'n\u00e3o informada'),d.regimeExec?'- Regime de execu\u00e7\u00e3o: '+d.regimeExec:'',d.valorEstimado?'- Valor estimado: '+d.valorEstimado:'',d.dataAbertura?'- Data de abertura: '+d.dataAbertura:'','- Objeto: '+d.objeto];
  if(d.textoEdital){linhas.push('');linhas.push('TEXTO DO EDITAL:');linhas.push('"""');linhas.push(d.textoEdital);linhas.push('"""');}
  if(d.clausulas.length>0){linhas.push('');linhas.push('CL\u00c1USULAS INDIVIDUAIS PARA AN\u00c1LISE:');d.clausulas.forEach(function(cl,i){linhas.push('');linhas.push('[Cl\u00e1usula '+(i+1)+(cl.titulo?' \u2014 '+cl.titulo:'')+']');linhas.push(cl.texto);});}
  linhas.push('');linhas.push('FOCOS DE AN\u00c1LISE SOLICITADOS:');d.focos.forEach(function(f){linhas.push('\u2022 '+f);});
  if(d.suspeitas.length){linhas.push('');linhas.push('ALERTAS PR\u00c9VIOS DO SOLICITANTE:');d.suspeitas.forEach(function(s){linhas.push('\u2022 '+s);});}
  if(d.artigos.length){linhas.push('');linhas.push('ARTIGOS PRIORIT\u00c1RIOS PARA VERIFICA\u00c7\u00c3O:');d.artigos.forEach(function(a){linhas.push('\u2022 '+a);});}
  if(d.obs){linhas.push('');linhas.push('CONTEXTO ADICIONAL: '+d.obs);}
  linhas=linhas.concat(['','---','','Gere um RELAT\u00d3RIO DE AN\u00c1LISE DE EDITAL completo e estruturado, seguindo este formato:','','## SUM\u00c1RIO EXECUTIVO','Breve s\u00edntese dos principais riscos encontrados e recomenda\u00e7\u00e3o geral (impugnar / participar com cautela / participar / revisar).','','## ACHADOS','Para cada irregularidade ou ponto de aten\u00e7\u00e3o encontrado, use o formato exato:','','ACHADO: [ALTO|M\u00c9DIO|BAIXO|CONFORME] \u2014 [T\u00edtulo do achado]','BASE LEGAL: [Artigo(s) da Lei 14.133/2021 ou outra norma aplic\u00e1vel]','DESCRI\u00c7\u00c3O: [Descri\u00e7\u00e3o do achado e por que \u00e9 problem\u00e1tico]','TRECHO DO EDITAL: [Trecho ou cl\u00e1usula espec\u00edfica que gera o problema, se identific\u00e1vel]','RECOMENDA\u00c7\u00c3O: [O que deve ser feito]','','Severidade:','- ALTO: v\u00edcio grave que pode ensejar impugna\u00e7\u00e3o judicial ou administrativa, direcionamento ilegal ou nulidade do certame','- M\u00c9DIO: cl\u00e1usula restritiva, amb\u00edgua ou desequilibrada que prejudica a competitividade ou os direitos do licitante','- BAIXO: ponto de aten\u00e7\u00e3o ou boa pr\u00e1tica recomendada que n\u00e3o impede a participa\u00e7\u00e3o','- CONFORME: cl\u00e1usula expressamente verificada e em conformidade com a lei','','## AN\u00c1LISE POR TEMA','Aprofunde os achados principais, agrupados pelos temas dos focos solicitados.','','## RECOMENDA\u00c7\u00d5ES FINAIS','Liste a\u00e7\u00f5es concretas em ordem de prioridade, com prazos e fundamentos legais.','','IMPORTANTE: Cite artigos, incisos e par\u00e1grafos exatos da Lei 14.133/2021. Baseie os achados apenas no texto fornecido. Quando o texto for insuficiente para uma conclus\u00e3o, indique quais informa\u00e7\u00f5es adicionais seriam necess\u00e1rias.']);
  promptGerado=linhas.filter(function(l){return l!==null&&l!==undefined;}).join('\n');
  document.getElementById('section-form').style.display='none';
  document.getElementById('section-prompt').style.display='block';
  setStep(4);
  document.getElementById('prompt-box').textContent=promptGerado;
  window.scrollTo({top:0,behavior:'smooth'});
}

function formatarAnalise(){
  var texto=document.getElementById('analise-paste').value.trim();
  if(!texto){showToast('Cole o texto gerado pela IA antes de formatar.');return;}
  var d=collectData();
  var dataHoje=new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'});
  var cabecalho='<div style="margin-bottom:18px;padding-bottom:16px;border-bottom:2px solid var(--border)"><div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:var(--blue);margin-bottom:6px">Relat\u00f3rio de an\u00e1lise de edital \u00b7 Lei 14.133/2021</div><h1 style="font-size:18px;font-weight:800;color:var(--text);margin-bottom:10px">'+esc(d.orgao||'\u00d3rg\u00e3o n\u00e3o informado')+'</h1><div style="display:flex;flex-wrap:wrap;gap:18px;font-size:12px;color:var(--muted)">'+(d.numEdital?'<span><strong style="color:var(--text-2)">Edital:</strong> '+esc(d.numEdital)+'</span>':'')+(d.modalidade?' <span><strong style="color:var(--text-2)">Modalidade:</strong> '+esc(d.modalidade)+'</span>':'')+(d.valorEstimado?' <span><strong style="color:var(--text-2)">Valor estimado:</strong> '+esc(d.valorEstimado)+'</span>':'')+(d.dataAbertura?' <span><strong style="color:var(--text-2)">Abertura:</strong> '+esc(d.dataAbertura)+'</span>':'')+' <span><strong style="color:var(--text-2)">An\u00e1lise gerada em:</strong> '+dataHoje+'</span></div>'+(d.objeto?'<div style="margin-top:10px;font-size:12.5px;color:var(--text-2);line-height:1.6"><strong>Objeto:</strong> '+esc(d.objeto)+'</div>':'')+'</div>';
  document.getElementById('doc-content').innerHTML=cabecalho+md2html(texto);
  document.getElementById('result-sub').textContent=d.orgao+' \u00b7 '+d.numEdital;
  document.getElementById('section-prompt').style.display='none';
  document.getElementById('section-result').style.display='block';
  setStep(5);
  window.scrollTo({top:0,behavior:'smooth'});
}

function md2html(md){
  md=md.replace(/^[-*_]{3,}\s*$/gm,'<hr style="border:none;border-top:1.5px solid var(--border);margin:16px 0">');
  var lines=md.split('\n');
  var out2=[];var i=0;
  while(i<lines.length){
    var am=lines[i].match(/^ACHADO:\s*(ALTO|M[EÉ]DIO|BAIXO|CONFORME)\s*[\u2014\-]+\s*(.+)$/i);
    if(am){
      var sev=am[1].normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();
      var titulo=am[2].trim();
      var sevMap={ALTO:{cls:'alto',label:'Alto risco',icon:'\ud83d\udd34'},MEDIO:{cls:'medio',label:'Risco m\u00e9dio',icon:'\ud83d\udfe0'},BAIXO:{cls:'baixo',label:'Baixo risco',icon:'\ud83d\udfe1'},CONFORME:{cls:'ok',label:'Conforme',icon:'\ud83d\udfe2'}};
      var s=sevMap[sev]||sevMap['MEDIO'];
      var bodyHtml='';i++;
      while(i<lines.length&&lines[i].trim()!==''&&!lines[i].match(/^ACHADO:/i)){
        var lm=lines[i].match(/^(BASE LEGAL|DESCRI[CÇ][AÃ]O|TRECHO DO EDITAL|RECOMENDA[CÇ][AÃ]O):\s*(.+)/i);
        if(lm){var labMap={'BASE LEGAL':'\ud83d\udccb Base legal','DESCRI\u00c7\u00c3O':'\ud83d\udcdd Descri\u00e7\u00e3o','DESCRICAO':'\ud83d\udcdd Descri\u00e7\u00e3o','TRECHO DO EDITAL':'\ud83d\udd0d Trecho do edital','RECOMENDA\u00c7\u00c3O':'\u2705 Recomenda\u00e7\u00e3o','RECOMENDACAO':'\u2705 Recomenda\u00e7\u00e3o'};var lbl=labMap[lm[1].toUpperCase()]||lm[1];bodyHtml+='<div style="margin-top:7px"><span style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:var(--muted)">'+lbl+'</span><div class="achado-body" style="margin-top:2px">'+esc(lm[2].trim())+'</div></div>';}
        else if(lines[i].trim())bodyHtml+='<div class="achado-body">'+esc(lines[i].trim())+'</div>';
        i++;
      }
      out2.push('ACHDBLK|'+s.cls+'|'+s.label+'|'+s.icon+'|'+titulo+'||'+bodyHtml);
    } else {out2.push(lines[i]);i++;}
  }
  var out=[];var inList=false;var listType='';
  var cntA=0,cntM=0,cntB=0,cntO=0;
  function closeList(){if(inList){out.push(listType==='ul'?'</ul>':'</ol>');inList=false;listType='';}}
  for(var j=0;j<out2.length;j++){
    var line=out2[j];
    var bm=line.match(/^ACHDBLK\|([^|]*)\|([^|]*)\|([^|]*)\|([^|]*)\|\|(.*)$/);
    if(bm){closeList();var cls=bm[1],lbl=bm[2],icn=bm[3],tit=bm[4],bh=bm[5];if(cls==='alto')cntA++;else if(cls==='medio')cntM++;else if(cls==='baixo')cntB++;else if(cls==='ok')cntO++;out.push('<div class="achado achado-'+cls+'"><button class="rm-btn" onclick="this.parentElement.remove()" title="Remover">\u2715</button><div class="achado-header"><span class="sev-badge sev-'+cls+'">'+icn+' '+lbl+'</span><span class="achado-titulo">'+tit+'</span></div>'+bh+'</div>');continue;}
    if(/^#### (.+)$/.test(line)){closeList();out.push('<h3>'+inlineFormat(line.slice(5))+'</h3>');continue;}
    if(/^### (.+)$/.test(line)){closeList();out.push('<h3>'+inlineFormat(line.slice(4))+'</h3>');continue;}
    if(/^## (.+)$/.test(line)){closeList();out.push('<h2>'+inlineFormat(line.slice(3))+'</h2>');continue;}
    if(/^# (.+)$/.test(line)){closeList();out.push('<h1>'+inlineFormat(line.slice(2))+'</h1>');continue;}
    if(/^\s*[-•*] (.+)$/.test(line)){var txt=line.replace(/^\s*[-•*]\s*/,'');if(!inList||listType!=='ul'){closeList();out.push('<ul>');inList=true;listType='ul';}out.push('<li>'+inlineFormat(txt)+'</li>');continue;}
    if(/^\d+\.\s+(.+)$/.test(line)){var txt2=line.replace(/^\d+\.\s+/,'');if(!inList||listType!=='ol'){closeList();out.push('<ol>');inList=true;listType='ol';}out.push('<li>'+inlineFormat(txt2)+'</li>');continue;}
    if(!line.trim()){closeList();out.push('');continue;}
    closeList();out.push('<p>'+inlineFormat(line)+'</p>');
  }
  closeList();
  var html=out.join('\n');
  if(cntA+cntM+cntB+cntO>0){
    var sumHTML='<div class="sumario"><div class="sumario-item sumario-alto"><div class="sumario-num">'+cntA+'</div><div class="sumario-label">Alto risco</div></div><div class="sumario-item sumario-medio"><div class="sumario-num">'+cntM+'</div><div class="sumario-label">Risco m\u00e9dio</div></div><div class="sumario-item sumario-baixo"><div class="sumario-num">'+cntB+'</div><div class="sumario-label">Baixo risco</div></div><div class="sumario-item sumario-ok"><div class="sumario-num">'+cntO+'</div><div class="sumario-label">Conformes</div></div></div>';
    html=html.replace(/<\/h2>/,function(m){return m+sumHTML;});
  }
  return html;
}
function inlineFormat(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\*\*\*(.+?)\*\*\*/g,'<strong><em>$1</em></strong>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*(.+?)\*/g,'<em>$1</em>').replace(/`(.+?)`/g,'<code>$1</code>');}

