function salvarHTML(){
  var state={version:'1',savedAt:new Date().toISOString(),elistData:JSON.parse(JSON.stringify(elistData)),clausulas:getClausulas(),fields:{orgao:document.getElementById('orgao').value,'num-edital':document.getElementById('num-edital').value,modalidade:_resolveOutro('modalidade'),'regime-exec':document.getElementById('regime-exec').value,'valor-estimado':document.getElementById('valor-estimado').value,'data-abertura':document.getElementById('data-abertura').value,objeto:document.getElementById('objeto').value,'texto-edital':document.getElementById('texto-edital').value,finalidade:document.getElementById('finalidade').value,'finalidade-outro':document.getElementById('finalidade-outro')?document.getElementById('finalidade-outro').value:'','modalidade-outro':document.getElementById('modalidade-outro')?document.getElementById('modalidade-outro').value:'','regime-exec-outro':document.getElementById('regime-exec-outro')?document.getElementById('regime-exec-outro').value:'','perfil-outro':document.getElementById('perfil-outro')?document.getElementById('perfil-outro').value:'','obs-extras':document.getElementById('obs-extras').value},checkedPerfis:getChecked('perfil-grid'),checkedFocos:getChecked('focos-grid'),promptGerado:promptGerado,resultHTML:document.getElementById('doc-content').innerHTML,currentPage:currentPage,currentSection:document.getElementById('section-result').style.display==='block'?'result':document.getElementById('section-prompt').style.display==='block'?'prompt':'form'};
  var pageHTML=document.documentElement.outerHTML;
  var stateTag='\n<script id="of-saved-state" type="application/json">'+JSON.stringify(state)+'<\/script>';
  var finalHTML=pageHTML.replace(/<\/body>/,stateTag+'\n</body>');
  var blob=new Blob([finalHTML],{type:'text/html;charset=utf-8'});
  var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;
  var nome=(state.fields['num-edital']||'analise').replace(/[^a-zA-Z0-9]/g,'-').toLowerCase().slice(0,40);
  a.download='of-edital-'+nome+'-'+new Date().toISOString().slice(0,10)+'.html';
  document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);
  showToast('\u2713 An\u00e1lise salva em HTML!');
}
function importarHTML(input){
  var file=input.files[0];if(!file)return;
  if(!file.name.endsWith('.html')){showToast('Importe um arquivo .html gerado por esta ferramenta.');return;}
  var reader=new FileReader();
  reader.onload=function(e){try{var html=e.target.result;var match=html.match(/<script[^>]*id="of-saved-state"[^>]*>([\s\S]*?)<\/script>/);if(!match)throw new Error('Arquivo inv\u00e1lido ou n\u00e3o foi gerado por esta ferramenta.');importarEstado(JSON.parse(match[1]));showToast('\u2713 An\u00e1lise importada com sucesso!');}catch(err){showToast('Erro ao importar: '+err.message);}};
  reader.readAsText(file);input.value='';
}
function importarEstado(state){
  Object.assign(elistData,state.elistData||{});Object.keys(elistData).forEach(function(id){er(id);});
  var f=state.fields||{};Object.keys(f).forEach(function(id){var el=document.getElementById(id);if(el)el.value=f[id]||'';});
  (state.checkedPerfis||[]).forEach(function(val){document.querySelectorAll('#perfil-grid input').forEach(function(chk){if(chk.value===val){chk.checked=true;chk.closest('label').classList.add('checked');}});});
  (state.checkedFocos||[]).forEach(function(val){document.querySelectorAll('#focos-grid input').forEach(function(chk){if(chk.value===val){chk.checked=true;chk.closest('label').classList.add('checked');}});});
  (state.clausulas||[]).forEach(function(cl){adicionarClausula(cl.titulo,cl.texto);});
  promptGerado=state.promptGerado||'';if(promptGerado)document.getElementById('prompt-box').textContent=promptGerado;
  if(typeof toggleFinalidadeOutro==='function')toggleFinalidadeOutro();if(typeof toggleOutro==='function'){toggleOutro('modalidade');toggleOutro('regime-exec');}
  var sec=state.currentSection||'form';
  if(sec==='result'&&state.resultHTML){document.getElementById('section-form').style.display='none';document.getElementById('section-prompt').style.display='none';document.getElementById('section-result').style.display='block';document.getElementById('doc-content').innerHTML=state.resultHTML;setStep(5);}
  else if(sec==='prompt'){document.getElementById('section-form').style.display='none';document.getElementById('section-result').style.display='none';document.getElementById('section-prompt').style.display='block';setStep(4);}
  else{var pg=Math.min(state.currentPage||1,TOTAL_FORM_PAGES);for(var i=1;i<=TOTAL_FORM_PAGES;i++)document.getElementById('page-'+i).style.display=i===pg?'block':'none';currentPage=pg;setStep(pg);}
}
