// ─── UPLOAD DE ARQUIVO (PDF / DOCX / HTML / TXT) — bibliotecas inline ─────────
function handleArquivoEdital(input) {
  var file = input.files[0];
  if (!file) return;
  var ext = file.name.split('.').pop().toLowerCase();
  var allowed = ['pdf','docx','doc','html','htm','txt'];
  if (allowed.indexOf(ext) === -1) {
    showToast('Formato não suportado. Use PDF, DOCX, HTML ou TXT.');
    input.value = '';
    return;
  }
  if (file.size > 30 * 1024 * 1024) {
    showToast('Arquivo muito grande. Máximo 30 MB.');
    input.value = '';
    return;
  }
  var nomeEl = document.getElementById('upload-nome');
  if (nomeEl) { nomeEl.textContent = file.name; nomeEl.style.display = 'block'; }
  setUploadStatus('Carregando arquivo…', 'loading');
  if (ext === 'pdf') {
    extrairPDF(file);
  } else if (ext === 'docx' || ext === 'doc') {
    extrairDOCX(file);
  } else if (ext === 'html' || ext === 'htm') {
    extrairHTML(file);
  } else {
    extrairTXT(file);
  }
}

function setUploadStatus(msg, state) {
  var el = document.getElementById('upload-status');
  if (!el) return;
  el.textContent = msg;
  el.style.display = msg ? 'block' : 'none';
  el.className = 'upload-status upload-status-' + (state || 'info');
}

function preencherTexto(texto) {
  texto = texto
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{4,}/g, '\n\n\n')
    .trim();
  var ta = document.getElementById('texto-edital');
  ta.value = texto;
  var chars = texto.length;
  setUploadStatus('\u2713 Texto extraído — ' + chars.toLocaleString('pt-BR') + ' caracteres · ' + ta.value.split('\n').length.toLocaleString('pt-BR') + ' linhas. Revise e continue.', 'ok');
  ta.focus();
}

// ── HTML ─────────────────────────────────────────────────────────────────────
function extrairHTML(file) {
  var reader = new FileReader();
  reader.onload = function(e) {
    try {
      var parser = new DOMParser();
      var doc = parser.parseFromString(e.target.result, 'text/html');
      // Remove scripts, styles, nav, footer boilerplate
      ['script','style','noscript','nav','footer','header','aside'].forEach(function(tag) {
        doc.querySelectorAll(tag).forEach(function(el) { el.remove(); });
      });
      var text = htmlNodeToText(doc.body || doc.documentElement);
      if (!text.trim()) { setUploadStatus('Não foi possível extrair texto do HTML.', 'error'); return; }
      preencherTexto(text);
    } catch(err) {
      setUploadStatus('Erro ao processar HTML: ' + err.message, 'error');
    }
  };
  reader.readAsText(file, 'UTF-8');
}

function htmlNodeToText(node) {
  if (!node) return '';
  var BLOCK = {DIV:1,P:1,H1:1,H2:1,H3:1,H4:1,H5:1,H6:1,LI:1,TR:1,SECTION:1,ARTICLE:1,BLOCKQUOTE:1,PRE:1,ADDRESS:1,CAPTION:1,THEAD:1,TBODY:1,TFOOT:1,DT:1,DD:1,FIGURE:1,FIGCAPTION:1};
  var SKIP = {SCRIPT:1,STYLE:1,NOSCRIPT:1,SVG:1,MATH:1};
  var buf = [];
  function walk(n) {
    if (n.nodeType === 3) { // text node
      var t = n.textContent;
      if (t.trim()) buf.push(t);
      return;
    }
    if (n.nodeType !== 1) return;
    var tag = n.tagName;
    if (SKIP[tag]) return;
    if (tag === 'BR') { buf.push('\n'); return; }
    if (tag === 'TD' || tag === 'TH') {
      var prev = buf[buf.length-1];
      if (prev && prev !== '\n' && prev !== '\t') buf.push('\t');
    }
    var isBlock = BLOCK[tag];
    if (isBlock) { var last = buf[buf.length-1]; if (last && last !== '\n') buf.push('\n'); }
    Array.prototype.forEach.call(n.childNodes, walk);
    if (isBlock) buf.push('\n');
    if (tag === 'TR') buf.push('\n');
  }
  walk(node);
  return buf.join('');
}

// ── TXT ──────────────────────────────────────────────────────────────────────
function extrairTXT(file) {
  var reader = new FileReader();
  reader.onload = function(e) {
    var texto = e.target.result;
    if (!texto.trim()) { setUploadStatus('Arquivo de texto vazio.', 'error'); return; }
    preencherTexto(texto);
  };
  reader.readAsText(file, 'UTF-8');
}

// ── PDF ──────────────────────────────────────────────────────────────────────
function extrairPDF(file) {
  var reader = new FileReader();
  reader.onload = function(e) {
    try {
      var pdfjsLib = window['pdfjs-dist/build/pdf'];
      if (!pdfjsLib) { setUploadStatus('Erro interno: leitor de PDF não disponível.', 'error'); return; }
      var _workerEl = document.getElementById('pdf-worker-src');
      if (_workerEl) {
        var _workerBlob = new Blob([_workerEl.textContent], {type: 'application/javascript'});
        pdfjsLib.GlobalWorkerOptions.workerSrc = URL.createObjectURL(_workerBlob);
      }
      var typedarray = new Uint8Array(e.target.result);
      pdfjsLib.getDocument({ data: typedarray, useWorkerFetch: false, isEvalSupported: false, useSystemFonts: true }).promise.then(function(pdf) {
        var totalPages = pdf.numPages;
        var pageTexts = [];
        setUploadStatus('Extraindo texto — 0/' + totalPages + ' páginas…', 'loading');
        var processPage = function(n) {
          if (n > totalPages) {
            preencherTexto(pageTexts.join('\n\n--- Página ' + n + ' ---\n\n').replace(/--- Página \d+ ---\n\n$/, ''));
            return;
          }
          pdf.getPage(n).then(function(page) {
            page.getTextContent({ includeMarkedContent: true, disableCombineTextItems: false }).then(function(content) {
              pageTexts.push(pdfItemsToText(content.items, n));
              setUploadStatus('Extraindo texto — ' + n + '/' + totalPages + ' páginas…', 'loading');
              processPage(n + 1);
            });
          }).catch(function() { pageTexts.push(''); processPage(n + 1); });
        };
        processPage(1);
      }).catch(function(err) {
        setUploadStatus('Não foi possível ler o PDF. O arquivo pode estar protegido ou corrompido.', 'error');
      });
    } catch(err) {
      setUploadStatus('Erro ao processar PDF: ' + err.message, 'error');
    }
  };
  reader.readAsArrayBuffer(file);
}

function pdfItemsToText(items, pageNum) {
  // Group items into lines by Y position, then sort each line by X
  var lines = {};
  var lineOrder = [];
  items.forEach(function(item) {
    if (!item.str && item.type !== 'beginMarkedContent') return;
    if (!item.str || !item.str.trim()) return;
    var y = Math.round(item.transform[5]);
    var x = item.transform[4];
    if (!lines[y]) { lines[y] = []; lineOrder.push(y); }
    lines[y].push({ x: x, str: item.str, w: item.width || 0 });
  });
  // Sort lines top-to-bottom (descending Y in PDF coords)
  lineOrder.sort(function(a, b) { return b - a; });
  var result = [];
  var prevY = null;
  lineOrder.forEach(function(y) {
    // Detect paragraph gap (large Y jump)
    if (prevY !== null && (prevY - y) > 14) { result.push(''); }
    // Sort items in line left-to-right
    var lineItems = lines[y].sort(function(a, b) { return a.x - b.x; });
    // Join with space, detect column breaks (large X gap)
    var lineParts = [];
    var lastX = null;
    var lastW = 0;
    lineItems.forEach(function(it) {
      if (lastX !== null && (it.x - (lastX + lastW)) > 20) {
        lineParts.push('  ');  // column gap
      }
      lineParts.push(it.str);
      lastX = it.x;
      lastW = it.w;
    });
    var lineStr = lineParts.join('').replace(/\s+/g, ' ').trim();
    if (lineStr) result.push(lineStr);
    prevY = y;
  });
  return result.join('\n');
}

// ── DOCX ─────────────────────────────────────────────────────────────────────
function extrairDOCX(file) {
  var reader = new FileReader();
  reader.onload = function(e) {
    try {
      if (!window.mammoth) { setUploadStatus('Erro interno: leitor de DOCX não disponível.', 'error'); return; }
      // Convert to HTML first to preserve table structure, then strip tags
      window.mammoth.convertToHtml({ arrayBuffer: e.target.result }).then(function(result) {
        if (!result.value || !result.value.trim()) {
          // Fallback to raw text
          return window.mammoth.extractRawText({ arrayBuffer: e.target.result });
        }
        var parser = new DOMParser();
        var doc = parser.parseFromString(result.value, 'text/html');
        var text = htmlNodeToText(doc.body);
        if (!text.trim()) { setUploadStatus('Não foi possível extrair texto do DOCX.', 'error'); return; }
        preencherTexto(text);
      }).then(function(rawResult) {
        // This runs only if we returned the fallback promise above
        if (rawResult && rawResult.value) preencherTexto(rawResult.value);
      }).catch(function() {
        setUploadStatus('Erro ao ler o DOCX. Tente outro arquivo.', 'error');
      });
    } catch(err) {
      setUploadStatus('Erro ao processar DOCX: ' + err.message, 'error');
    }
  };
  reader.readAsArrayBuffer(file);
}

function extrairDOCX(file) {
  var reader = new FileReader();
  reader.onload = function(e) {
    try {
      if (!window.mammoth) { setUploadStatus('Erro interno: leitor de DOCX não disponível.', 'error'); return; }
      window.mammoth.extractRawText({ arrayBuffer: e.target.result }).then(function(result) {
        if (!result.value || !result.value.trim()) {
          setUploadStatus('Não foi possível extrair texto. O arquivo pode estar protegido ou vazio.', 'error');
          return;
        }
        preencherTexto(result.value);
      }).catch(function() {
        setUploadStatus('Erro ao ler o DOCX. Tente outro arquivo.', 'error');
      });
    } catch(err) {
      setUploadStatus('Erro ao processar DOCX: ' + err.message, 'error');
    }
  };
  reader.readAsArrayBuffer(file);
}

